// ────────────────────────────────────────────────────────────────────────────
// The home's own assessments and care plan fields (v90).
//
// THE CANONICAL COPY IS backend/src/services/customAssessments.ts; the app's
// copy is generated by scripts/sync-shared.mjs.
//
// A manager builds an assessment from questions, points and score bands, or
// adds fields to any area of the care plan. The definition is plain JSON, so
// it can be stored, versioned and shown back exactly. This file turns a
// definition into the same Tool the built-in assessments use, so the runner,
// the server's scoring, the record chain and "Add to care plan" all work the
// same way — and it refuses a definition that would not work (validate*).
//
// A published definition never changes: editing makes a new version, and
// every completed assessment points at the exact version it was scored with.
// Every result says plainly that this is the home's own assessment, not a
// validated scale. Pure; tested in backend/tests/customassessments.test.mjs.
// ────────────────────────────────────────────────────────────────────────────
import { base, str, list, type Answers, type Option, type Question, type Tool, type Level } from './assessmentCore';
import type { DetailField } from './careDetails';

export const CUSTOM_LIMITS = { questions: 60, options: 20, bands: 6, actions: 20, text: 300, points: 100, reviewDays: 730 } as const;

export interface CustomOptionDef { value: string; label: string; points?: number; alert?: string }
export interface CustomQuestionDef {
  key: string; label: string; hint?: string;
  type: 'choice' | 'multi' | 'yesno' | 'number' | 'text' | 'date';
  options?: CustomOptionDef[]; optional?: boolean; unit?: string; min?: number; max?: number;
}
export interface CustomBandDef { from: number; label: string; level: 'low' | 'medium' | 'high'; actions: string[]; reviewDays: number; fact?: string }
export interface CustomToolDef {
  name: string; shortName: string; purpose: string; who: string;
  /** The care plan area it belongs to (built-in or the home's own). */
  domain: string;
  whenNeeded?: string;
  scored: boolean;
  sections: { title: string; intro?: string; questions: CustomQuestionDef[] }[];
  /** Scored: from lowest to highest, the first from 0. Not scored: exactly one. */
  bands: CustomBandDef[];
}

const KEY = /^[a-z][a-z0-9_]{0,39}$/;
const LEVELS = ['low', 'medium', 'high'];

function optionsOf(q: CustomQuestionDef): CustomOptionDef[] {
  if (q.type === 'yesno') {
    const given = q.options || [];
    return [
      { value: 'yes', label: 'Yes', points: given.find(o => o.value === 'yes')?.points, alert: given.find(o => o.value === 'yes')?.alert },
      { value: 'no', label: 'No', points: given.find(o => o.value === 'no')?.points, alert: given.find(o => o.value === 'no')?.alert },
    ];
  }
  return q.options || [];
}

/** The highest score the definition can give. */
export function maxScore(def: CustomToolDef): number {
  let total = 0;
  for (const s of def.sections) for (const q of s.questions) {
    const pts = optionsOf(q).map(o => Math.max(0, Number(o.points) || 0));
    if (!pts.length) continue;
    total += q.type === 'multi' ? pts.reduce((a, b) => a + b, 0) : Math.max(...pts);
  }
  return total;
}

/** Everything wrong with a definition, in words a manager can act on. Empty = publishable. */
export function validateCustomTool(def: CustomToolDef, knownDomains: string[]): string[] {
  const e: string[] = [];
  const text = (v: unknown, what: string, min = 1, max: number = CUSTOM_LIMITS.text) => {
    const s = typeof v === 'string' ? v.trim() : '';
    if (s.length < min) e.push(`${what} is needed.`); else if (s.length > max) e.push(`${what} is too long (${max} characters at most).`);
  };
  if (!def || typeof def !== 'object') return ['The definition is empty.'];
  text(def.name, 'A name', 3, 80);
  text(def.shortName, 'A short name', 2, 24);
  text(def.purpose, 'What it is for', 5);
  text(def.who, 'Who completes it, and when', 5);
  if (!knownDomains.includes(def.domain)) e.push('Choose the area of the care plan it belongs to.');
  if (def.whenNeeded && def.whenNeeded.length > CUSTOM_LIMITS.text) e.push('"When needed" is too long.');
  const qs = (def.sections || []).flatMap(s => s.questions || []);
  if (!def.sections?.length || !qs.length) e.push('Add at least one question.');
  if (qs.length > CUSTOM_LIMITS.questions) e.push(`At most ${CUSTOM_LIMITS.questions} questions.`);
  for (const s of def.sections || []) text(s.title, 'Every section needs a title', 1, 80);
  const keys = new Set<string>();
  qs.forEach((q, i) => {
    const where = `Question ${i + 1}`;
    if (!KEY.test(q.key || '')) e.push(`${where}: internal key is invalid.`);
    if (keys.has(q.key)) e.push(`${where}: duplicate key "${q.key}".`); keys.add(q.key);
    text(q.label, `${where}: the question`);
    if (!['choice', 'multi', 'yesno', 'number', 'text', 'date'].includes(q.type)) e.push(`${where}: unknown type.`);
    if (q.type === 'choice' || q.type === 'multi') {
      const o = q.options || [];
      if (o.length < 2) e.push(`${where}: give at least 2 answers to choose from.`);
      if (o.length > CUSTOM_LIMITS.options) e.push(`${where}: at most ${CUSTOM_LIMITS.options} answers.`);
      const vals = new Set<string>();
      o.forEach((x, j) => {
        if (!KEY.test(x.value || '')) e.push(`${where}, answer ${j + 1}: internal value is invalid.`);
        if (vals.has(x.value)) e.push(`${where}: two answers share a value.`); vals.add(x.value);
        text(x.label, `${where}, answer ${j + 1}`);
      });
    }
    for (const x of optionsOf(q)) {
      if (x.points !== undefined && x.points !== null && (!Number.isInteger(Number(x.points)) || Number(x.points) < 0 || Number(x.points) > CUSTOM_LIMITS.points)) {
        e.push(`${where}: points must be whole numbers from 0 to ${CUSTOM_LIMITS.points}.`);
      }
      if (x.alert && x.alert.length > CUSTOM_LIMITS.text) e.push(`${where}: a warning is too long.`);
    }
    if (q.type === 'number' && q.min !== undefined && q.max !== undefined && Number(q.min) >= Number(q.max)) e.push(`${where}: the lowest allowed number must be below the highest.`);
  });
  const bands = def.bands || [];
  if (def.scored) {
    if (bands.length < 1 || bands.length > CUSTOM_LIMITS.bands) e.push(`Give between 1 and ${CUSTOM_LIMITS.bands} score bands.`);
    if (bands[0] && Number(bands[0].from) !== 0) e.push('The first score band must start at 0.');
    for (let i = 1; i < bands.length; i++) if (!(Number(bands[i].from) > Number(bands[i - 1].from))) e.push(`Score band ${i + 1} must start above band ${i}.`);
    const top = maxScore(def);
    if (bands.length && Number(bands[bands.length - 1].from) > top) e.push(`The last band starts at ${bands[bands.length - 1].from}, but the highest possible score is ${top}.`);
    if (top === 0 && qs.length) e.push('A scored assessment needs answers with points.');
  } else if (bands.length !== 1) e.push('An assessment without a score has one outcome (what to do, and when to review).');
  bands.forEach((b, i) => {
    const where = def.scored ? `Score band ${i + 1}` : 'The outcome';
    text(b.label, `${where}: a name`, 1, 80);
    if (!LEVELS.includes(b.level)) e.push(`${where}: choose low, medium or high.`);
    if (!Array.isArray(b.actions) || !b.actions.filter(a => a && a.trim()).length) e.push(`${where}: say what to do.`);
    if ((b.actions || []).length > CUSTOM_LIMITS.actions) e.push(`${where}: at most ${CUSTOM_LIMITS.actions} actions.`);
    (b.actions || []).forEach(a => { if (a && a.length > CUSTOM_LIMITS.text) e.push(`${where}: an action is too long.`); });
    if (!Number.isInteger(Number(b.reviewDays)) || Number(b.reviewDays) < 1 || Number(b.reviewDays) > CUSTOM_LIMITS.reviewDays) e.push(`${where}: review in 1 to ${CUSTOM_LIMITS.reviewDays} days.`);
    if (b.fact && b.fact.length > 120) e.push(`${where}: what carers see is too long (120 characters).`);
  });
  return Array.from(new Set(e));
}

/** The same Tool the built-in assessments are, from a definition. */
export function customToTool(def: CustomToolDef, meta: { key: string; version: number }): Tool {
  const questions: Question[] = [];
  const sections = def.sections.map((s, i) => ({
    key: `s${i + 1}`, title: s.title, intro: s.intro,
    questions: s.questions.map(q => {
      const options: Option[] | undefined = ['choice', 'multi', 'yesno'].includes(q.type)
        ? optionsOf(q).map(o => ({ value: o.value, label: o.label, points: o.points !== undefined && o.points !== null ? Number(o.points) : undefined }))
        : undefined;
      const qq: Question = {
        key: q.key, label: q.label, hint: q.hint,
        type: q.type === 'yesno' ? 'choice' : q.type,
        options, optional: q.optional, unit: q.unit,
        min: q.min !== undefined ? Number(q.min) : undefined, max: q.max !== undefined ? Number(q.max) : undefined,
      };
      questions.push(qq);
      return qq;
    }),
  }));
  const defQ = new Map(def.sections.flatMap(s => s.questions).map(q => [q.key, q]));
  const top = maxScore(def);
  const tool: Tool = {
    key: meta.key, name: def.name, shortName: def.shortName, version: `custom:${meta.key}:v${meta.version}`,
    purpose: def.purpose, who: def.who, domain: def.domain, scored: !!def.scored, whenNeeded: def.whenNeeded || undefined,
    sources: [{ label: 'The home\'s own assessment — not a validated scale', url: 'https://www.cqc.org.uk/guidance-providers/regulations/regulation-12-safe-care-treatment' }],
    sections,
    evaluate(a: Answers) {
      const r = base(tool, a, def.domain);
      let score = 0;
      for (const q of questions) {
        const src = defQ.get(q.key)!;
        const opts = optionsOf(src);
        const chosen = q.type === 'multi' ? list(a[q.key]) : str(a[q.key]) ? [str(a[q.key])] : [];
        for (const v of chosen) {
          const o = opts.find(x => x.value === v);
          if (!o) continue;
          const p = Math.max(0, Number(o.points) || 0);
          score += p;
          if (p > 0) r.reasons.push(`${q.label}: ${o.label} (+${p})`);
          if (o.alert) r.warnings.push(o.alert);
        }
      }
      const bands = [...def.bands].sort((x, y) => Number(x.from) - Number(y.from));
      const band = def.scored ? (bands.filter(b => score >= Number(b.from)).pop() || bands[0]) : bands[0];
      r.score = def.scored ? score : null;
      r.maxScore = def.scored ? top : undefined;
      r.storedScore = def.scored ? score : 0;
      // Scored or not, the home chose a level for each outcome.
      r.level = band.level as Level;
      r.headline = def.scored ? `${band.label} (${def.shortName} ${score})` : band.label;
      r.actions = band.actions.filter(x => x && x.trim());
      r.reviewDays = Number(band.reviewDays) || 28;
      r.reviewNote = 'Set by the home for this assessment.';
      r.reasons.push('This is the home\'s own assessment, not a validated scale.');
      if (band.fact) r.facts.push(band.fact);
      r.plan = {
        domain: def.domain, riskLevel: band.level,
        need: `${def.shortName}: ${r.headline}.`,
        interventions: r.actions.slice(),
      };
      return r;
    },
  };
  return tool;
}

// ── The home's own care plan fields ─────────────────────────────────────────

export interface CustomFieldDef {
  key: string; label: string; type: 'text' | 'select' | 'number' | 'bool' | 'date' | 'list';
  options?: string[]; unit?: string; min?: number; max?: number; hint?: string;
  /** Show to carers in "Know before you help". */
  fact?: boolean; tone?: 'red' | 'amber' | 'info';
}

export function validateCustomField(f: CustomFieldDef): string[] {
  const e: string[] = [];
  if (!f || typeof f !== 'object') return ['The field is empty.'];
  if (!/^x_[a-z0-9_]{1,40}$/.test(f.key || '')) e.push('Internal key is invalid.');
  if (!f.label || f.label.trim().length < 2 || f.label.length > 80) e.push('Give the field a name (2–80 characters).');
  if (!['text', 'select', 'number', 'bool', 'date', 'list'].includes(f.type)) e.push('Choose what kind of answer it takes.');
  if (f.type === 'select') {
    const o = (f.options || []).map(x => String(x).trim()).filter(Boolean);
    if (o.length < 2) e.push('A choice needs at least 2 options.');
    if (o.length > CUSTOM_LIMITS.options) e.push(`At most ${CUSTOM_LIMITS.options} options.`);
    if (new Set(o).size !== o.length) e.push('Two options are the same.');
    if (o.some(x => x.length > 80)) e.push('An option is too long (80 characters).');
  }
  if (f.type === 'number' && f.min !== undefined && f.max !== undefined && Number(f.min) >= Number(f.max)) e.push('The lowest allowed number must be below the highest.');
  if (f.tone && !['red', 'amber', 'info'].includes(f.tone)) e.push('Unknown colour.');
  if (f.hint && f.hint.length > 160) e.push('The hint is too long.');
  return e;
}

/** A field definition as the care plan uses it, including what carers see. */
export function customFieldToDetail(f: CustomFieldDef): DetailField {
  const options = f.type === 'select' ? (f.options || []).map(o => ({ value: o, label: o })) : undefined;
  const show = (v: unknown) => f.type === 'bool' ? (v === true ? f.label : null)
    : f.type === 'list' ? (Array.isArray(v) && v.length ? `${f.label}: ${(v as string[]).join(', ')}` : null)
    : `${f.label}: ${v}${f.unit ? ` ${f.unit}` : ''}`;
  return {
    key: f.key, label: f.label, type: f.type, options, unit: f.unit, hint: f.hint,
    min: f.min !== undefined ? Number(f.min) : undefined, max: f.max !== undefined ? Number(f.max) : undefined,
    fact: f.fact ? (v: unknown) => (v === null || v === undefined || v === '' || v === false ? null : show(v)) : undefined,
    tone: f.tone === 'red' || f.tone === 'amber' ? f.tone : undefined,
  };
}
